    public static class AntonioTabucchi
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Bisogna parlare, parlare finché è possibile perché poi un bel giorno avremo la bocca piena di terra.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Come può essere presente la notte. Fatta solo di se stessa, è assoluta, ogni spazio è suo, si impone di sola presenza, della stessa presenza del fantasma che sai che è lì di fronte a te ma è dappertutto, anche alle tue spalle, e se ti rifugi in un piccolo luogo di luce di esso sei prigioniero perché intorno, come un mare che circonda il tuo piccolo faro, c'è l'invalicabile presenza della notte.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "I dubbi sono come macchie su una camicia bianca, fresca di bucato. La missione di ogni intellettuale e di ogni scrittore è di instillare i dubbi per la perfezione, perché la perfezione genera ideologie, dittatori e idee totalitariste.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La lettera è un equivoco messaggero.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La notte è calda, la notte è lunga, la notte è magnifica per ascoltare storie.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Le parve di essere quel bambino che all'improvviso si ritrovava con un palloncino floscio tra le mani, qualcuno glielo aveva rubato, ma no, il palloncino c'era ancora, gli avevano soltanto sottratto l'aria che c'era dentro. Era dunque così, il tempo era aria e lei l'aveva lasciata esalare da un forellino minuscolo di cui non si era accorta?", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Per conoscere un luogo non è sempre necessario esserci stati.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Può succedere che il senso della vita di qualcuno sia quello, insensato, di cercare delle voci scomparse, e magari un giorno di crederle di trovarle, un giorno che non aspettava più, una sera che è stanco, e vecchio, e suona sotto la luna, e raccoglie tutte le voci che vengono dalla sabbia.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Questo è il grande problema di coloro che sentono troppo e capiscono troppo: che potremmo essere tante cose, ma la vita è una sola e ci obbliga a essere solo una cosa, quella che gli altri pensano che noi siamo.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "So cos'è uno scrittore. Semplice, è qualcuno che conosce l'angusta prigione del proprio Io (o Ego) e che cerca di vedere le cose dall'altra parte. E che attraverso i suoi personaggi si sforza di essere un altro, molti altri, tanti altri quanto è possibile. Anche un albanese.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Un libro è un deposito di suggestioni e di immagini che ogni lettore usa come vuole.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Manolo il Gitano era seduto a un tavolino sotto la pergola dello spaccio. Indossava una giacca nera e un cappello a falde larghe, alla spagnola. Aveva l'aria di una perduta nobiltà: la miseria gli si leggeva tutta nel volto e nella camicia sbrindellata sul petto.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Firmino sentì un'ondata di simpatia per quella città per la quale aveva provato, senza conoscerla, una certa diffidenza. Concluse che tutti siamo preda dei pregiudizi e che senza accorgersene lui aveva mancato di dialettica, quella fondamentale dialettica a cui Lukács tanto teneva.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La Guarda Nacional è un istituzione militare, è proprio una bella incarnazione della Grundnorm, la cosa incomincia a interessarmi, anche perché forse lei non sa quante persone sono state uccise o seviziate nei nostri simpatici commissariati negli ultimi tempi.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Lei continua a deludermi, giovanotto, rispose l'avvocato, cerca a tutti i costi di essere inferiore a se stesso, non dobbiamo mai essere inferiori a noi stessi, cos'è che ha detto di me?", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "la [[tortura]] può venire da ogni parte, e questo il vero problema.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "È una persona, disse, si ricordi di questo, giovanotto, prima di tutto è una persona.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Cerchi di essere delicato con lei, abbia molto tatto, Wanda è una creatura fragile come il cristallo, una parola storta e le vengono le crisi di pianto.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "la filosofia sembra che si occupi solo della verità, ma forse dice solo fantasie, e la letteratura sembra che si occupi solo di fantasie, ma forse dice la verità.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Le ragioni del cuore sono le più importanti, bisogna sempre seguire le ragioni del cuore, questo i dieci comandamenti non lo dicono, ma glielo dico io.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Stai bene a sentire, Pereira, disse Silva, tu credi ancora nell'opinione pubblica?, ebbene, l'opinione pubblica è un trucco che hanno inventato gli anglosassoni, gli inglesi e gli americani, sono loro che ci stanno smerdando, scusa la parola, con questa idea dell'opinione pubblica, noi non abbiamo mai avuto il loro sistema politico, non abbiamo le loro tradizioni, non sappiamo cosa sono le trade unions, noi siamo gente del Sud, Pereira, e ubbidiamo a chi grida di più, a chi comanda.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Non c'è niente di cui vergognarsi a questo mondo, disse Pereira, se non si è rubato e se non si è disonorato il padre e la madre.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Non si sentì rassicurato, sentì invece una grande nostalgia, di cosa non saprebbe dirlo, ma era una grande nostalgia di una vita passata e di una vita futura, sostiene Pereira.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La smetta di frequentare il passato, cerchi di frequentare il futuro.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La vita non è in ordine alfabetico come credete voi. Appare... un po' qua e un po' là, come meglio crede, sono briciole, il problema è raccoglierle dopo, è un mucchietto di sabbia, e qual è il granello che sostiene l'altro? A volte quello che sta sul cocuzzolo e sembra sorretto da tutto il mucchietto, è proprio lui che tiene insieme tutti gli altri, perché quel mucchietto non ubbidisce alle leggi della fisica, togli il granello che credevi non sorreggesse niente e crolla tutto, la sabbia scivola, si appiattisce e non ti resta altro che farci ghirigori col dito, degli andirivieni, sentieri che non portano da nessuna parte, e dai e dai, stai lì a tracciare andirivieni, ma dove sarà quel benedetto granello che teneva tutto insieme... e poi un giorno il dito si ferma da sé, non ce la fa più a fare ghirigori, sulla [[sabbia]] c'è un tracciato strano, un [[disegno]] senza logica e senza costrutto, e ti viene un sospetto, che il senso di tutta quella roba lì erano i ghirigori.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Che strano, pensaci un po', mio padre studiava le vite vicinissime col microscopio, mio nonno cercava quelle lontanissime col canocchiale, entrambi con le lenti. Ma la vita si scopre a occhio nudo, né troppo lontana né troppo vicina, ad altezza d'uomo.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Se ti metti a guardare nelle pieghe piú nascoste della società, qualsiasi essa sia, scopri la pazzia. Ma quelli che hanno avuto il coraggio di farlo erano pazzi...", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "La vita non si racconta, te l'ho già detto, la vita si vive, e mentre la vivi è già persa, è scappata.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Ora Tristano è davvero stanco, non ha più fiato, lo senti, avrebbe voglia di dormire, ma non il breve sonno di un'inizione, a lungo, come deve essere lungo il sonno che compensi la fatica di aver vissuto.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Ti ho cercato, amore mio, in ogni atomo di te che è disperso nell'universo. Ne ho raccolti quanti mi era possibile, nella terra, nell'aria, nel mare, negli sguardi e nei gesti degli uomini.", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "Scrittore, chi sei tu per avere i dubbi di coscienza di qualcuno che non hai mai conosciuto?", Author = "Antonio Tabucchi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Tabucchi", Text = "È una bella foto, gliela regalo, la metta sulla copertina del suo libro, non è Tristano ma lo è un po', visto che è suo padre... Ci gira le spalle come se ci dicesse addio, che poi è quello che ho fatto in tutti questi giorni con lei, e che ora sto facendo per l'ultima volta... Guardi la pendola, che ore sono? Le sembrerà stupido, ma voglio saperlo, è l'ultima cosa che voglio sapere... comunque domani è un altro giorno, come si dice.", Author = "Antonio Tabucchi" },
        };
    }
